 274|// Run starts the main loop. It blocks until ctx is cancelled.
 275|func (o *Orchestrator) Run(ctx context.Context) {
 276|	// Startup cleanup: clear stale agent assignments left from previous runs.
 277|	o.cleanupOrphanedAssignments()
 278|
 279|	// Generate repo map for the default branch worktree at startup.
 280|	go o.worktree.GenerateRepoMapForMain()
 281|
 282|	ticker := time.NewTicker(o.tick)
 283|	defer ticker.Stop()
 284|	o.logger.Info("orchestrator started", "project_id", o.projectID)
 285|	for {
 286|		select {
 287|		case <-ctx.Done():
 288|			o.logger.Info("orchestrator stopping")
 289|			return
 290|		case <-ticker.C:
 291|			o.doTick(ctx)
 292|		}
 293|	}
 294|}
