 353|		o.logger.Error("query planning tasks", "error", err)
 354|	}
 355|	for i := range planningTasks {
 356|		if err := o.processPlanning(&planningTasks[i]); err != nil {
 357|			o.logger.Error("process planning", "task_id", planningTasks[i].ID, "error", err)
 358|		}
 359|	}
 360|
 361|	// 4b. Process TEST_WRITING parent tasks.
 362|	var testWritingTasks []model.Task
 363|	if err := o.db.Where("project_id = ? AND status = ? AND parent_task_id IS NULL",
 364|		o.projectID, model.StatusTestWriting).Find(&testWritingTasks).Error; err != nil {
 365|		o.logger.Error("doTick: query test_writing tasks", "error", err)
 366|	} else {
 367|		for i := range testWritingTasks {
 368|			if err := o.processTestWriting(&testWritingTasks[i]); err != nil {
 369|				o.logger.Error("doTick: processTestWriting", "task_id", testWritingTasks[i].ID, "error", err)
 370|			}
 371|		}
 372|	}
 373|
 374|	// 4. Process IN_PROGRESS parent tasks -> schedule subtasks, check completion.
 375|	var inProgressTasks []model.Task
 376|	if err := o.db.Where("project_id = ? AND status = ? AND parent_task_id IS NULL", o.projectID, model.StatusInProgress).
 377|		Find(&inProgressTasks).Error; err != nil {
 378|		o.logger.Error("query in_progress tasks", "error", err)
 379|	}
 380|	for i := range inProgressTasks {
 381|		task := &inProgressTasks[i]
 382|		if task.Category.IsQuickFix() {
 383|			// Quick fix tasks are top-level with no subtasks.
 384|			// Agent completion is handled by processAgentResult (step 2).
 385|			if task.AssignedAgentID == nil {
 386|				// Check if this is an empty-work retry (agent completed
 387|				// without commits and onAgentEmptyWork cleared the agent
 388|				// for respawn). In that case, respawn a new agent instead
 389|				// of transitioning to merging.
 390|				needsRetry := false
 391|				if task.Context != nil {
 392|					if _, ok := task.Context["empty_work"]; ok {
 393|						needsRetry = true
 394|					}
 395|				}
 396|				if needsRetry {
 397|					if err := o.respawnQuickFixAgent(task); err != nil {
 398|						o.logger.Error("quickfix respawn", "task_id", task.ID, "error", err)
 399|					}
 400|				} else {
