 442|	if err := o.db.Where("project_id = ? AND status = ?", o.projectID, model.StatusPaused).
 443|		Find(&pausedTasks).Error; err != nil {
 444|		o.logger.Error("query paused tasks", "error", err)
 445|	}
 446|	for i := range pausedTasks {
 447|		if err := o.handlePaused(&pausedTasks[i]); err != nil {
 448|			o.logger.Error("handle paused", "task_id", pausedTasks[i].ID, "error", err)
 449|		}
 450|	}
