 471|func (o *Orchestrator) isWorkAlreadyMerged(subtask *model.Task, featureWorktree string) bool {
 472|	if subtask.AssignedAgentID == nil {
 473|		return false
 474|	}
 475|
 476|	var ag model.Agent
 477|	if err := o.db.First(&ag, "id = ?", subtask.AssignedAgentID).Error; err != nil {
 478|		return false
 479|	}
 480|
 481|	if ag.WorktreeBranch == "" {
 482|		return false
 483|	}
 484|
 485|	// Check if agent branch tip is an ancestor of feature HEAD.
 486|	_, err := worktree.RunGit(
 487|		[]string{"merge-base", "--is-ancestor", ag.WorktreeBranch, "HEAD"},
 488|		featureWorktree,
 489|	)
 490|	return err == nil // exit code 0 means it IS an ancestor
