 510|func (o *Orchestrator) recoverStuckAgents() {
 511|	var agents []model.Agent
 512|	if err := o.db.Where("project_id = ? AND status = ?", o.projectID, model.AgentWorking).
 513|		Find(&agents).Error; err != nil {
 514|		o.logger.Error("recover stuck agents: query", "error", err)
 515|		return
 516|	}
 517|
 518|	now := time.Now()
 519|	for _, ag := range agents {
 520|		// OpenCode agents don't use .claude/agent-idle — they're monitored
 521|		// by process exit. Skip to avoid false idle detection from stale files.
 522|		if ag.Provider == string(model.ProviderOpenCode) {
 523|			continue
 524|		}
 525|
 526|		// Grace period: skip agents that were recently spawned. This prevents
 527|		// a race where a stale idle signal file (from a previous agent in the
 528|		// same worktree) causes a freshly-spawned agent to be immediately
 529|		// treated as stuck before it has time to begin work.
 530|		if ag.CreatedAt.After(now.Add(-agentSpawnGracePeriod)) {
 531|			continue
 532|		}
 533|
 534|		idleSignal := filepath.Join(ag.WorktreePath, ".claude", "agent-idle")
 535|		if _, err := os.Stat(idleSignal); err != nil {
 536|			continue // signal file doesn't exist — agent is genuinely working
 537|		}
 538|
 539|		o.logger.Info("recovering stuck agent (idle signal found)", "agent_id", ag.ID, "type", ag.AgentType)
 540|
 541|		if ag.CurrentTaskID == nil {
 542|			continue
 543|		}
 544|
 545|		var task model.Task
 546|		if err := o.db.First(&task, "id = ?", ag.CurrentTaskID).Error; err != nil {
 547|			o.logger.Error("recover stuck agent: load task", "agent_id", ag.ID, "error", err)
 548|			continue
 549|		}
 550|
 551|		if err := o.onAgentCompleted(&ag, &task); err != nil {
 552|			o.logger.Error("recover stuck agent: on completed", "agent_id", ag.ID, "error", err)
 553|		}
 554|	}
